head.script:
scwin.onpageload = function () {
	window.opener = null;
};
scwin.openPop2_onclick = function (e) {
	var options = {
		id: "popup2",
		name: "popup2",
		type: "browserPopup",
		width: "800px",
		height: "400px",
		popupUrl: "/websquare/blank.html",
		accessibility: true,
		features: "noopener"
	};
	$p.openPopup("", options);
};
